import { Queue } from 'bullmq';
import { Redis } from 'ioredis';

const connection = new Redis({ maxRetriesPerRequest: null });
const queue = new Queue('relatorios', { connection });

// Cria OU atualiza o agendamento pelo id: rodar isso a cada boot não duplica nada
await queue.upsertJobScheduler(
  'resumo-diario',                                    // id do agendamento
  { pattern: '0 8 * * *', tz: 'America/Sao_Paulo' },  // cron: todo dia às 8h
  { name: 'gerar-resumo', data: { tipo: 'diario' } }, // modelo de cada job gerado
);

// Intervalo fixo em vez de cron
await queue.upsertJobScheduler('limpeza', { every: 15 * 60_000 }, { name: 'limpar-temporarios' });

const agendamentos = await queue.getJobSchedulers();
console.log(agendamentos.map((a) => `${a.key} → próximo em ${new Date(a.next!).toISOString()}`));

await queue.removeJobScheduler('limpeza'); // para de gerar jobs
// O worker não muda nada: cada disparo vira um job comum na fila

import { Queue, Worker, type Job } from 'bullmq';
import { Redis } from 'ioredis';

const connection = new Redis({ maxRetriesPerRequest: null });
const queue = new Queue('chamadas-api', { connection });

// No máximo 10 jobs por segundo NESTA fila, somando todos os workers
const worker = new Worker('chamadas-api', processar, {
  connection,
  concurrency: 5,
  limiter: { max: 10, duration: 1_000 },
});

// Limite dinâmico: a API externa respondeu 429 Too Many Requests
async function processar(job: Job<{ url: string }>) {
  const res = await fetch(job.data.url);
  if (res.status === 429) {
    const esperaMs = Number(res.headers.get('retry-after') ?? 60) * 1_000;
    await queue.rateLimit(esperaMs); // segura a fila inteira por esse tempo
    throw Worker.RateLimitError();   // devolve o job para a fila SEM gastar tentativa
  }
  if (!res.ok) throw new Error(`HTTP ${res.status}`); // erro comum: conta tentativa
  return res.json();
}

const queue = new Queue('emails', { connection });

// priority: 1 é a mais alta. Jobs SEM prioridade passam na frente dos priorizados
await queue.add('email', { para: 'comum@ex.com' }, { priority: 10 });
await queue.add('email', { para: 'vip@ex.com' }, { priority: 1 });

// Deduplicação: enquanto o primeiro job existir (esperando ou rodando),
// adds com o mesmo id de deduplicação são ignorados
const j1 = await queue.add('reindexar', { produtoId: 42 }, { deduplication: { id: 'reindexar-42' } });
const j2 = await queue.add('reindexar', { produtoId: 42 }, { deduplication: { id: 'reindexar-42' } });
console.log(j1.id === j2.id); // true: o segundo add devolveu o job que já existia

// Com ttl: ignora repetições só durante 5s ("o usuário salvou 10 vezes seguidas")
await queue.add('sincronizar', { userId: 'u1' }, { deduplication: { id: 'sync-u1', ttl: 5_000 } });

console.log(await queue.getJobCounts('waiting', 'prioritized'));
// { waiting: 2, prioritized: 2 }  → reindexar e sincronizar; os dois emails priorizados

// jobId fixo vs deduplication: com jobId, o id do job é o seu e o conflito dura
// enquanto o job existir no Redis (até concluído). deduplication mantém ids
// normais e controla só a repetição, com ttl se você quiser.

const flow = new FlowProducer({ connection });

// O pai só roda depois que TODOS os filhos terminarem
const arvore = await flow.add({
  name: 'montar-relatorio',
  queueName: 'relatorios',
  data: { mes: '2026-10' },
  children: [
    { name: 'vendas', queueName: 'consultas', data: { fonte: 'vendas' } },
    { name: 'estoque', queueName: 'consultas', data: { fonte: 'estoque' } },
  ],
});

const consultas = new Worker('consultas', async (job) => ({ fonte: job.data.fonte, linhas: 100 }), {
  connection,
});

const relatorios = new Worker('relatorios', async (job) => {
  // Resultados dos filhos, indexados pela chave de cada um no Redis
  const filhos = await job.getChildrenValues<{ fonte: string; linhas: number }>();
  const total = Object.values(filhos).reduce((soma, f) => soma + f.linhas, 0);
  return { mes: job.data.mes, total };
}, { connection });

