// ── s5.ts ──
// queue e connection: os mesmos das seções anteriores
// Quantos jobs em cada estado: base para métricas e alertas
console.log(await queue.getJobCounts('waiting', 'active', 'delayed', 'failed', 'completed'));

// Reprocessar a "dead letter": jobs que falharam de vez
for (const job of await queue.getFailed(0, 99)) {
  console.log(job.id, job.failedReason, job.attemptsMade);
  await job.retry(); // volta para a fila de espera
}

// Pausar (manutenção do SMTP, incidente) e retomar
await queue.pause();
await queue.resume();

// Limpar concluídos com mais de 1h, até 1000 por vez
await queue.clean(60 * 60_000, 1_000, 'completed');

// Job "stalled": o worker morreu ou travou o event loop e parou de renovar o lock.
// O BullMQ percebe e devolve o job para a fila sozinho.
// Para CPU pesada, use um processor em arquivo separado (sandboxed),
// que roda em outra thread e não trava o worker:
const imagens = new Worker('imagens', new URL('./redimensionar.ts', import.meta.url), {
  connection,
  useWorkerThreads: true,
});

// ── redimensionar.ts ──
import type { SandboxedJob } from 'bullmq';

// Roda em outra thread: CPU pesada aqui não trava o worker principal
export default async function (job: SandboxedJob<{ arquivo: string }>) {
  await job.updateProgress(50);
  return { arquivo: job.data.arquivo, largura: 800 };
}
